package net.moz.driver;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.content.pm.ServiceInfo;import android.database.Cursor;import android.database.sqlite.*;import android.location.*;import android.os.*;import android.webkit.CookieManager;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import java.util.concurrent.*;
public class TrackingService extends Service implements LocationListener {
 static volatile boolean running=false;static volatile String blockedEpoch=null;private LocationManager manager;private QueueDb db;private ScheduledExecutorService io;private ExecutorService disk;private String trip,owner;private volatile String epoch;private volatile boolean verified=false,closing=false,collecting=false;private long lastFix=0;private final Handler guard=new Handler(Looper.getMainLooper());private final String channel="moz_tracking";
 static android.content.SharedPreferences authorization(Context c){return c.getSharedPreferences("moz_authorization",Context.MODE_PRIVATE);}
 static boolean previouslyAuthorized(Context c,String owner,String trip,String epoch){return (owner+"|"+trip+"|"+epoch).equals(authorization(c).getString("grant",""));}
 static void remember(Context c,String owner,String trip,String epoch){authorization(c).edit().putString("grant",owner+"|"+trip+"|"+epoch).commit();}
 static void forget(Context c){authorization(c).edit().remove("grant").commit();}
 @Override public void onCreate(){super.onCreate();running=true;db=new QueueDb(this);manager=(LocationManager)getSystemService(LOCATION_SERVICE);io=Executors.newSingleThreadScheduledExecutor();disk=Executors.newSingleThreadExecutor();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(channel,"MOZ — Rastreamento de viagem",NotificationManager.IMPORTANCE_LOW));}
 Notification notification(String message){Intent open=new Intent(this,MainActivity.class);PendingIntent p=PendingIntent.getActivity(this,1,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Intent stop=new Intent(this,TrackingService.class).setAction("STOP");PendingIntent q=PendingIntent.getService(this,2,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,channel).setContentTitle("MOZ Driver").setContentText(message).setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentIntent(p).setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Interromper GPS",q).build()).build();}
 void status(String message){if(!closing)getSystemService(NotificationManager.class).notify(101,notification(message));}
 boolean renew()throws Exception{JSONObject me=request("/me",null);if(!owner.equals(me.optString("id"))||!"driver".equals(me.optString("role"))||!me.optBoolean("identityVerified"))throw new SecurityException("Conta diferente ou não autorizada");JSONObject auth=request("/driver/tracking",null);String next=auth.optString("trackingSince","");if(!trip.equals(auth.optString("tripId",""))||!epoch.equals(next)||!auth.optBoolean("offlineAllowed"))return false;remember(this,owner,trip,epoch);verified=true;return true;}
 @Override public int onStartCommand(Intent i,int flags,int startId){
 if(i==null||"STOP".equals(i.getAction())){if(i!=null&&epoch!=null){blockedEpoch=epoch;authorization(this).edit().putString("blockedEpoch",epoch).commit();forget(this);}stopSelf();return START_NOT_STICKY;}
 String t=i.getStringExtra("trip"),o=i.getStringExtra("owner"),expected=i.getStringExtra("epoch");if(expected==null||expected.equals(blockedEpoch)){stopSelf();return START_NOT_STICKY;}
 try{UUID.fromString(t);UUID.fromString(o);Instant.parse(expected);}catch(Exception e){stopSelf();return START_NOT_STICKY;}
 if(trip!=null)return START_NOT_STICKY;
 trip=t;owner=o;epoch=expected;if(Build.VERSION.SDK_INT>=29)startForeground(101,notification("Verificando viagem…"),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(101,notification("Verificando viagem…"));
 if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return START_NOT_STICKY;}
 io.execute(()->{try{boolean allowed;try{allowed=renew();}catch(SecurityException denied){throw denied;}catch(IOException offline){allowed=previouslyAuthorized(this,owner,trip,epoch);}
 if(!allowed){verified=false;haltGps();if(!db.hasPending(owner,trip)){forget(this);stopSelf();return;}}else verified=true;
 if(allowed&&!db.hasFinish(owner,trip))guard.post(this::beginGps);else status("Encerramento local · aguardando sincronização");
 io.scheduleWithFixedDelay(this::flush,0,5,TimeUnit.SECONDS);
 }catch(Exception e){status("Não foi possível validar a viagem.");stopSelf();}});return START_NOT_STICKY;}
 void beginGps(){if(!verified||closing||collecting)return;try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,5000,0,this,Looper.getMainLooper());collecting=true;status("GPS ativo durante a viagem. Pode bloquear a tela.");}catch(SecurityException|IllegalArgumentException e){status("Permissão ou provedor GPS indisponível.");stopSelf();}}
 void haltGps(){collecting=false;guard.post(()->{try{manager.removeUpdates(this);}catch(Exception ignored){}});}
 @Override public void onLocationChanged(Location l){if(!verified||closing||!collecting)return;if(db.hasFinish(owner,trip)){haltGps();return;}if(l.getTime()<Instant.parse(epoch).toEpochMilli()||l.getTime()-lastFix<4000)return;lastFix=l.getTime();String id=UUID.randomUUID().toString();try{JSONObject f=new JSONObject();f.put("id",id);f.put("at",Instant.ofEpochMilli(l.getTime()).toString());f.put("trackingSince",epoch);f.put("lat",l.getLatitude());f.put("lon",l.getLongitude());f.put("accuracy",l.getAccuracy());f.put("speed",l.hasSpeed()?l.getSpeed()*3.6:JSONObject.NULL);disk.execute(()->{try{db.insert(id,owner,trip,f.toString());}catch(Exception e){status("Falha no armazenamento local do GPS.");}});}catch(Exception ignored){}}
 @Override public void onProviderDisabled(String p){status("GPS desligado. Ative a localização do aparelho.");}
 @Override public void onProviderEnabled(String p){status("GPS disponível.");}
 @Override public void onStatusChanged(String p,int status,Bundle extras){}
 static class HttpFailure extends IOException{final int code;HttpFailure(int code){super("HTTP "+code);this.code=code;}}
 HttpURLConnection connect(String path)throws IOException{String cookies=CookieManager.getInstance().getCookie(MainActivity.BASE);if(cookies==null||cookies.isEmpty())throw new HttpFailure(401);HttpURLConnection c=(HttpURLConnection)new URL(MainActivity.BASE+"/api"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Cookie",cookies);c.setRequestProperty("X-MOZ-Request","1");c.setRequestProperty("Accept","application/json");return c;}
 JSONObject response(HttpURLConnection c)throws Exception{int code=c.getResponseCode();if(code==403)throw new SecurityException("Vínculo não autorizado");if(code<200||code>=300)throw new HttpFailure(code);try(InputStream is=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=is.read(b))!=-1)out.write(b,0,n);return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}
 JSONObject request(String path,JSONArray body)throws Exception{HttpURLConnection c=connect(path);try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}}return response(c);}finally{c.disconnect();}}
 static void field(OutputStream os,String boundary,String key,String value)throws IOException{os.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+key+"\"\r\n\r\n"+value+"\r\n").getBytes(StandardCharsets.UTF_8));}
 JSONObject upload(PodItem p)throws Exception{HttpURLConnection c=connect("/trips/"+trip+"/pod");String boundary="moz"+UUID.randomUUID().toString().replace("-","");try{c.setRequestMethod("POST");c.setDoOutput(true);c.setChunkedStreamingMode(65536);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);try(OutputStream os=c.getOutputStream()){field(os,boundary,"id",p.id);field(os,boundary,"captured",p.captured);field(os,boundary,"stageId",p.stage);os.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"comprovante\"\r\nContent-Type: application/octet-stream\r\n\r\n").getBytes(StandardCharsets.UTF_8));try(InputStream in=new FileInputStream(p.path)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)os.write(buf,0,n);}os.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));}return response(c);}finally{c.disconnect();}}
 void flush(){if(closing)return;try{
 boolean allowed=renew();if(!allowed){verified=false;haltGps();}
 if(db.hasFinish(owner,trip))haltGps();
 // Wait for writes already handed to the durable queue, then replay GPS before each photo.
 disk.submit(()->{}).get();
 for(int round=0;round<40&&!closing;round++){
 PodItem p=db.nextPod(owner,trip);JSONArray batch=db.batch(owner,trip,p==null?null:p.captured);
 if(batch.length()>0){JSONObject r=request("/trips/"+trip+"/fixes",batch);JSONArray ids=r.getJSONArray("acceptedIds"),discarded=r.optJSONArray("discardIds");for(int k=0;k<ids.length();k++)db.delete(ids.getString(k),owner,trip);if(discarded!=null)for(int k=0;k<discarded.length();k++)db.delete(discarded.getString(k),owner,trip);if(!r.optBoolean("trackingActive",false)){allowed=false;verified=false;haltGps();forget(this);}if(ids.length()+(discarded==null?0:discarded.length())==0)break;continue;}
 if(p!=null){try{JSONObject r=upload(p);String s=r.optString("status");if(p.finish&&!"Finalizada".equals(s)){db.review(p.id,"Comprovante recebido; encerramento pendente de validação.");haltGps();}else{db.removePod(p);if("Finalizada".equals(s)||"Cancelada".equals(s)){allowed=false;verified=false;haltGps();forget(this);}}}catch(HttpFailure ex){if(ex.code==400||ex.code==404){db.review(p.id,"Comprovante preservado; servidor requer conferência.");if(p.finish)haltGps();}else throw ex;}continue;}
 break;
 }
 if(!allowed){forget(this);status("Viagem encerrada ou cancelada.");stopSelf();return;}
 if(db.hasFinish(owner,trip))status("Encerramento local · sincronização ou conferência pendente");else status("GPS ativo · dados sincronizados quando houver internet");
 }catch(SecurityException e){verified=false;forget(this);haltGps();status("Acesso revogado. GPS interrompido.");stopSelf();}catch(Exception e){status(db.hasFinish(owner,trip)?"Encerrada no aparelho · aguardando conexão":"Sem internet · GPS e dados armazenados no aparelho");}}
 @Override public void onDestroy(){closing=true;running=false;verified=false;collecting=false;guard.removeCallbacksAndMessages(null);if(manager!=null)try{manager.removeUpdates(this);}catch(Exception ignored){}if(io!=null)io.shutdown();if(disk!=null)disk.shutdown();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
 static class PodItem{String id,captured,stage,path;boolean finish;PodItem(Cursor c){id=c.getString(0);captured=c.getString(1);stage=c.getString(2);path=c.getString(3);finish=c.getInt(4)!=0;}}
 static class QueueDb extends SQLiteOpenHelper{
 QueueDb(Context c){super(c,"moz_gps.db",null,2);}
 void pods(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS pods(id TEXT PRIMARY KEY, owner TEXT NOT NULL, trip TEXT NOT NULL, stage TEXT NOT NULL, captured TEXT NOT NULL, path TEXT NOT NULL, finish INTEGER NOT NULL, state TEXT NOT NULL, message TEXT)");}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE fixes(id TEXT PRIMARY KEY, owner TEXT NOT NULL, trip TEXT NOT NULL, json TEXT NOT NULL)");pods(db);}
 @Override public void onUpgrade(SQLiteDatabase db,int a,int b){if(a<2)pods(db);}
 void insert(String id,String owner,String trip,String json){ContentValues v=new ContentValues();v.put("id",id);v.put("owner",owner);v.put("trip",trip);v.put("json",json);getWritableDatabase().insertOrThrow("fixes",null,v);}
 JSONArray batch(String owner,String trip,String before)throws JSONException{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().query("fixes",new String[]{"json"},"owner=? AND trip=?",new String[]{owner,trip},null,null,"rowid","100")){while(c.moveToNext()){JSONObject f=new JSONObject(c.getString(0));if(before!=null&&Instant.parse(f.getString("at")).isAfter(Instant.parse(before)))break;a.put(f);}}return a;}
 void delete(String id,String owner,String trip){getWritableDatabase().delete("fixes","id=? AND owner=? AND trip=?",new String[]{id,owner,trip});}
 void addPod(String id,String owner,String trip,String stage,String captured,String path,boolean finish){ContentValues v=new ContentValues();v.put("id",id);v.put("owner",owner);v.put("trip",trip);v.put("stage",stage);v.put("captured",captured);v.put("path",path);v.put("finish",finish?1:0);v.put("state","pending");getWritableDatabase().insertOrThrow("pods",null,v);}
 PodItem nextPod(String owner,String trip){try(Cursor c=getReadableDatabase().query("pods",new String[]{"id","captured","stage","path","finish"},"owner=? AND trip=? AND state='pending'",new String[]{owner,trip},null,null,"captured","1")){return c.moveToFirst()?new PodItem(c):null;}}
 boolean hasPending(String owner,String trip){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM pods WHERE owner=? AND trip=? AND state='pending' LIMIT 1",new String[]{owner,trip})){return c.moveToFirst();}}
 boolean hasFinish(String owner,String trip){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM pods WHERE owner=? AND trip=? AND finish=1 LIMIT 1",new String[]{owner,trip})){return c.moveToFirst();}}
 JSONArray pending(String owner,String trip)throws JSONException{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().query("pods",new String[]{"id","captured","stage","finish","state","message"},"owner=? AND trip=?",new String[]{owner,trip},null,null,"captured")){while(c.moveToNext()){JSONObject p=new JSONObject();p.put("id",c.getString(0));p.put("captured",c.getString(1));p.put("stageId",c.getString(2));p.put("finish",c.getInt(3)!=0);p.put("state",c.getString(4));p.put("message",c.getString(5));a.put(p);}}return a;}
 void review(String id,String message){ContentValues v=new ContentValues();v.put("state","review");v.put("message",message);getWritableDatabase().update("pods",v,"id=?",new String[]{id});}
 void removePod(PodItem p){getWritableDatabase().delete("pods","id=?",new String[]{p.id});new File(p.path).delete();}
 }
}